def run(_context):
    import adsk.core, adsk.fusion, adsk.cam
    app = adsk.core.Application.get()
    cam = adsk.cam.CAM.cast(app.activeDocument.products.itemByProductType('CAMProductType'))
    # Find TIW library
    libMgr = adsk.cam.CAMManager.get().libraryManager
    toolLibs = libMgr.toolLibraries
    # search local libraries
    urls = []
    def walk(url, depth=0):
        for child in toolLibs.childAssetURLs(url):
            urls.append(child.toString())
            walk(child, depth+1)
    from adsk.core import URL
    for loc in [adsk.cam.LibraryLocations.LocalLibraryLocation, adsk.cam.LibraryLocations.Fusion360LibraryLocation]:
        root = toolLibs.urlByLocation(loc)
        try:
            walk(root)
        except Exception as e:
            print("walk err", loc, e)
    for u in urls:
        if 'TIW' in u or 'tiw' in u:
            print("FOUND:", u)
    print("total urls:", len(urls))
    for u in urls[:20]:
        print(" ", u)
    return "done"

