    app = adsk.core.Application.get()
    cam = adsk.cam.CAM.cast(app.activeDocument.products.itemByProductType('CAMProductType'))
    setup = cam.setups.item(0)
    for o in setup.operations:
        info=[]
        try:
            tp=o.toolpath
            info.append(f"moves={tp.movementCount if hasattr(tp,'movementCount') else '?'}")
        except Exception as e:
            info.append(f"tp_err={e}")
        try:
            info.append(f"warning={o.hasWarning}")
        except: pass
        try:
            info.append(f"error={o.hasError if hasattr(o,'hasError') else '?'}")
        except: pass
        try:
            info.append(f"isValid={o.isValid}")
        except: pass
        print(o.name, info)
    return "done"

